// Generated by write_viewer_params.py; presentation only, the STEP stays neutral.
// Pivots are chassis coordinates (mm): origin on the floor under the axle.
const geo = {"pivots": {"roll": [56.1221, -1.0695, 236.7174], "pitch": [16.0, 0.0, 234.5945], "yaw": [16.0, 0.0, 140.0], "pinion": [16.0, 37.0, 0.0], "wheel_L": [0.0, 85.0, 42.0], "wheel_R": [0.0, -85.0, 42.0]}, "wheel_radius": 42.0, "track": 170.0, "yaw_ratio": 1.0, "wheel_limit_deg": 1080, "travel": {"roll": [-18.0, 18.0], "pitch": [-22.0, 40.0], "yaw": [-55.0, 55.0]}};
const clamp = (value, min, max) => Math.max(min, Math.min(max, Number(value) || 0));
const rot = (axis, origin, angleDeg) => ({ rotate: { axis, origin, angleDeg } });
const RAD = Math.PI / 180;

// Differential drive from the two wheel angles: equal arcs translate, unequal
// arcs turn about the instantaneous centre on the axle line (x = 0).
function drivePose(leftDeg, rightDeg) {
  const sL = leftDeg * RAD * geo.wheel_radius;
  const sR = rightDeg * RAD * geo.wheel_radius;
  const turn = (sR - sL) / geo.track;
  const travel = (sL + sR) / 2;
  if (Math.abs(turn) < 1e-9) return { translate: [travel, 0, 0] };
  return rot([0, 0, 1], [0, travel / turn, 0], turn / RAD);
}

const wave = (progress) => Math.sin(2 * Math.PI * progress);
// Wheel angle for one full heading turn on the spot: each wheel rolls once
// round a circle of radius track / 2, i.e. pi * track of travel.
const SPIN_TURN_DEG = (geo.track / 2 / geo.wheel_radius) * 360;
const animations = {
  wheels_spin: {
    label: "Wheels spin in place",
    duration: 2,
    update({ progress, set }) {
      set("drive_on_floor", false);
      set("wheel_L_deg", 360 * progress);
      set("wheel_R_deg", 360 * progress);
    }
  },
  drive_forward_back: {
    label: "Drive forward and back",
    duration: 5,
    update({ progress, set }) {
      const angle = 540 * wave(progress);
      set("drive_on_floor", true);
      set("wheel_L_deg", angle);
      set("wheel_R_deg", angle);
    }
  },
  spin_turn: {
    // Out and back: a full turn leaves the wheels at ~729 deg, not a whole
    // number of wheel turns, so a one-way loop would jump the wheel index.
    label: "Turn 360° on the spot and back",
    duration: 8,
    update({ progress, set }) {
      const angle = SPIN_TURN_DEG * (1 - Math.cos(2 * Math.PI * progress)) / 2;
      set("drive_on_floor", true);
      set("wheel_L_deg", -angle);
      set("wheel_R_deg", angle);
    }
  },
  head_look_around: {
    label: "Head look around",
    duration: 8,
    update({ progress, set }) {
      const t = geo.travel;
      set("head_yaw_deg", t.yaw[1] * wave(progress));
      set("head_pitch_deg", (t.pitch[1] / 2) * Math.max(0, wave(2 * progress)) + (t.pitch[0] / 2) * Math.max(0, -wave(2 * progress)));
      set("head_roll_deg", (t.roll[1] / 2) * wave(progress + 0.25));
    }
  }
};

export default {
  manifest: { ...{
  "schemaVersion": 1,
  "step": {
    "path": "body-chassis/layout-02/body-chassis.step"
  },
  "parameters": {
    "head_roll_deg": {
      "type": "number",
      "label": "Head roll",
      "unit": "°",
      "min": -18.0,
      "max": 18.0,
      "step": 1,
      "default": 0
    },
    "head_pitch_deg": {
      "type": "number",
      "label": "Head pitch",
      "unit": "°",
      "min": -22.0,
      "max": 40.0,
      "step": 1,
      "default": 0
    },
    "head_yaw_deg": {
      "type": "number",
      "label": "Head yaw",
      "unit": "°",
      "min": -55.0,
      "max": 55.0,
      "step": 1,
      "default": 0
    },
    "wheel_L_deg": {
      "type": "number",
      "label": "Wheel left (+ = forward)",
      "unit": "°",
      "min": -1080,
      "max": 1080,
      "step": 5,
      "default": 0
    },
    "wheel_R_deg": {
      "type": "number",
      "label": "Wheel right (+ = forward)",
      "unit": "°",
      "min": -1080,
      "max": 1080,
      "step": 5,
      "default": 0
    },
    "drive_on_floor": {
      "type": "boolean",
      "label": "Wheels drive the robot on the floor",
      "default": true
    },
    "show_shell": {
      "type": "boolean",
      "label": "Show translucent shell",
      "default": true
    },
    "show_head": {
      "type": "boolean",
      "label": "Show RP-01 Layout 04 head",
      "default": true
    },
    "show_structure": {
      "type": "boolean",
      "label": "Show body/chassis structure",
      "default": true
    },
    "show_drive": {
      "type": "boolean",
      "label": "Show drivetrain",
      "default": true
    },
    "show_rear_tail": {
      "type": "boolean",
      "label": "Show rear skid/TCRT keel",
      "default": true
    },
    "show_electronics": {
      "type": "boolean",
      "label": "Show electronics",
      "default": true
    },
    "show_sensors": {
      "type": "boolean",
      "label": "Show sensors",
      "default": true
    },
    "show_audio": {
      "type": "boolean",
      "label": "Show speaker and microphones",
      "default": true
    },
    "show_harness": {
      "type": "boolean",
      "label": "Show harness routes",
      "default": true
    },
    "show_physics": {
      "type": "boolean",
      "label": "Show physics overlays",
      "default": false
    }
  },
  "features": {
    "frame_R": {
      "ref": "#o1.20.1.1,o1.22.1.2.1,o1.22.1.3.2,o1.22.1.3.4,o1.21.1.1.1,o1.21.1.1.2,o1.21.1.1.3,o1.21.1.2.1,o1.21.1.2.2,o1.21.1.2.3,o1.21.1.3.1,o1.21.1.3.2,o1.21.1.3.3,o1.21.1.5.1"
    },
    "frame_P": {
      "ref": "#o1.20.1.2,o1.22.1.1.2,o1.22.1.2.2,o1.22.1.3.3,o1.21.1.4.1,o1.21.1.4.2,o1.21.1.4.3"
    },
    "frame_Y": {
      "ref": "#o1.20.1.3,o1.22.1.1.3,o1.22.1.2.3,o1.22.1.1.4,o1.21.1.6.1,o1.21.1.6.2,o1.21.1.6.3,o1.20.2"
    },
    "yaw_pinion": {
      "ref": "#o1.19.2,o1.19.3"
    },
    "wheel_L": {
      "ref": "#o1.4,o1.6.4"
    },
    "wheel_R": {
      "ref": "#o1.5,o1.7.4"
    },
    "shell": {
      "ref": "#o1.16,o1.17,o1.18"
    },
    "head": {
      "ref": "#o1.20"
    },
    "structure": {
      "ref": "#o1.1,o1.2,o1.3,o1.19"
    },
    "drive": {
      "ref": "#o1.4,o1.5,o1.6,o1.7,o1.8,o1.9,o1.10"
    },
    "rear_tail": {
      "ref": "#o1.11"
    },
    "electronics": {
      "ref": "#o1.12"
    },
    "sensors": {
      "ref": "#o1.13"
    },
    "audio": {
      "ref": "#o1.14"
    },
    "harness": {
      "ref": "#o1.15,o1.21"
    },
    "physics": {
      "ref": "#o1.22,o1.23"
    }
  }
}, animations },
  update({ params, effects }) {
    const t = geo.travel;
    const roll = clamp(params.head_roll_deg, t.roll[0], t.roll[1]);
    const pitch = clamp(params.head_pitch_deg, t.pitch[0], t.pitch[1]);
    const yaw = clamp(params.head_yaw_deg, t.yaw[0], t.yaw[1]);
    const r = rot([1, 0, 0], geo.pivots.roll, roll);
    const p = rot([0, 1, 0], geo.pivots.pitch, pitch);
    const y = rot([0, 0, 1], geo.pivots.yaw, yaw);
    effects.transform("frame_R", { transforms: [r, p, y] });
    effects.transform("frame_P", { transforms: [p, y] });
    effects.transform("frame_Y", y);
    // External 1:1 spur mesh: the servo pinion turns the other way.
    effects.transform("yaw_pinion", rot([0, 0, 1], geo.pivots.pinion, -yaw / geo.yaw_ratio));

    const wl = clamp(params.wheel_L_deg, -geo.wheel_limit_deg, geo.wheel_limit_deg);
    const wr = clamp(params.wheel_R_deg, -geo.wheel_limit_deg, geo.wheel_limit_deg);
    // Positive rotation about +Y carries the tyre top toward +X: forward roll.
    effects.transform("wheel_L", rot([0, 1, 0], geo.pivots.wheel_L, wl));
    effects.transform("wheel_R", rot([0, 1, 0], geo.pivots.wheel_R, wr));
    if (params.drive_on_floor !== false) effects.transform("*", drivePose(wl, wr));

    for (const key of ["shell", "head", "structure", "drive", "rear_tail", "electronics", "sensors", "audio", "harness", "physics"]) {
      effects.visible(key, params[`show_${key}`] !== false);
    }
  }
};
